css:
.atlantico-sim-container {
    padding: 20px;
    background: linear-gradient(165deg, #f3f5f9 0%, #eef1f7 55%, #e8ecf4 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1e2a3a;
}

.atlantico-sim-header {
    background: linear-gradient(135deg, #0f2740 0%, #1b3c5e 52%, #27577f 100%);
    color: #f6f9fc;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 14px 34px rgba(15,39,64,0.32);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.12);
}

.atlantico-sim-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(214,168,84,0.16) 0%, transparent 60%);
    pointer-events: none;
}

.atlantico-sim-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.atlantico-sim-header h1 {
    font-size: 1.95rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.4px;
    font-family: Georgia, 'Times New Roman', serif;
}

.atlantico-sim-header p {
    font-size: 1rem;
    opacity: 0.92;
    margin: 0 0 14px 0;
    letter-spacing: 0.5px;
}

.atlantico-sim-clock {
    display: inline-block;
    background: rgba(0,0,0,0.26);
    border: 1px solid rgba(214,168,84,0.55);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.atlantico-sim-clock #deadlineDisplay {
    color: #ecc578;
    font-weight: 800;
    margin: 0 4px;
}

.atlantico-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #44566c;
    margin-bottom: 22px;
    font-weight: 600;
}

.atlantico-sim-period-counter span {
    margin: 0 3px;
}

.atlantico-sim-period-counter #currentDay,
.atlantico-sim-period-counter #maxPeriods {
    color: #1b3c5e;
    font-weight: 800;
}

.atlantico-sim-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(27,60,94,0.1);
    border: 1px solid rgba(27,60,94,0.28);
    border-radius: 999px;
    color: #1b3c5e;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.atlantico-sim-kpi-section {
    margin-bottom: 22px;
}

.atlantico-sim-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.atlantico-sim-kpi-cards-secondary {
    grid-template-columns: repeat(4, 1fr);
    margin-bottom: 0;
}

.atlantico-sim-kpi-card {
    background: #ffffff;
    border: 1px solid rgba(27,60,94,0.12);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 18px rgba(15,39,64,0.08);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.atlantico-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(15,39,64,0.16);
}

.atlantico-kpi-hero {
    border: 1px solid rgba(214,168,84,0.6);
    background: linear-gradient(160deg, #fdf8ee 0%, #ffffff 100%);
}

.atlantico-sim-kpi-label {
    font-size: 0.78rem;
    color: #647689;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 700;
}

.atlantico-sim-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #1e2a3a;
    line-height: 1.05;
}

.atlantico-kpi-hero .atlantico-sim-kpi-value {
    color: #b9821f;
}

.atlantico-kpi-small .atlantico-sim-kpi-value {
    font-size: 1.45rem;
    color: #1b3c5e;
}

.atlantico-sim-kpi-sub {
    font-size: 0.74rem;
    color: #8a98a8;
    margin-top: 8px;
    line-height: 1.3;
}

.atlantico-sim-kpi-bar-bg {
    height: 8px;
    background: rgba(27,60,94,0.1);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.atlantico-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.atlantico-behaviour-fill { background: linear-gradient(90deg, #b9821f, #ecc578); }
.atlantico-alignment-fill { background: linear-gradient(90deg, #1b3c5e, #3d77a8); }
.atlantico-measurement-fill { background: linear-gradient(90deg, #2f7d6a, #56b39b); }
.atlantico-fit-fill { background: linear-gradient(90deg, #6a4a8c, #9b78c0); }

/* ---- Briefing ---- */
.atlantico-sim-briefing {
    background: #ffffff;
    border: 1px solid rgba(27,60,94,0.12);
    border-left: 4px solid #b9821f;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(15,39,64,0.08);
}

.atlantico-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #b9821f;
    font-family: Georgia, 'Times New Roman', serif;
}

.atlantico-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #2c3a4b;
}

.atlantico-sim-briefing-text strong {
    color: #1b3c5e;
}

.atlantico-sim-briefing-text em {
    color: #6a4a8c;
    font-style: italic;
}

.atlantico-sim-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(185,130,31,0.1);
    border: 1px solid rgba(185,130,31,0.45);
    border-radius: 10px;
    color: #855c12;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.atlantico-sim-controls {
    background: #ffffff;
    border: 1px solid rgba(27,60,94,0.12);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(15,39,64,0.08);
}

.atlantico-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #1b3c5e;
    font-family: Georgia, 'Times New Roman', serif;
}

.atlantico-sim-decisions-note {
    font-size: 0.86rem;
    color: #647689;
    margin-bottom: 18px;
    font-style: italic;
}

.atlantico-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.atlantico-sim-input-group {
    display: flex;
    flex-direction: column;
}

.atlantico-sim-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #2c3a4b;
    margin-bottom: 7px;
}

.atlantico-sim-container .form-control {
    background-color: #ffffff;
    color: #1e2a3a;
    border: 1px solid rgba(27,60,94,0.25);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.atlantico-sim-container .form-control:focus {
    border-color: #1b3c5e;
    box-shadow: 0 0 0 3px rgba(27,60,94,0.18);
    background-color: #ffffff;
    color: #1e2a3a;
    outline: none;
}

.atlantico-sim-container select.form-control {
    background-color: #ffffff;
    color: #1e2a3a;
}

.atlantico-sim-container select.form-control option {
    background-color: #ffffff;
    color: #1e2a3a;
}

.atlantico-sim-hint {
    font-size: 0.76rem;
    color: #8a98a8;
    margin-top: 6px;
    line-height: 1.35;
}

.atlantico-sim-budget-meter {
    margin-top: 20px;
    padding: 14px 16px;
    background: rgba(27,60,94,0.05);
    border: 1px solid rgba(27,60,94,0.14);
    border-radius: 10px;
}

.atlantico-sim-budget-row {
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    color: #2c3a4b;
    margin-bottom: 8px;
    flex-wrap: wrap;
}

.atlantico-sim-budget-row #allocatedDisplay {
    font-size: 1.15rem;
    font-weight: 800;
    color: #1b3c5e;
}

.atlantico-sim-days-tag {
    margin-left: auto;
    padding: 3px 12px;
    background: rgba(106,74,140,0.12);
    border: 1px solid rgba(106,74,140,0.32);
    border-radius: 999px;
    color: #6a4a8c;
    font-size: 0.8rem;
    font-weight: 700;
}

.atlantico-sim-days-tag.atlantico-days-over {
    background: rgba(192,57,43,0.14);
    border-color: rgba(192,57,43,0.5);
    color: #b1372a;
}

.atlantico-sim-budget-bar-bg {
    height: 10px;
    background: rgba(27,60,94,0.12);
    border-radius: 6px;
    overflow: hidden;
}

.atlantico-sim-budget-bar-fill {
    height: 100%;
    border-radius: 6px;
    background: linear-gradient(90deg, #1b3c5e, #3d77a8);
    transition: width 0.4s ease, background 0.4s ease;
}

.atlantico-sim-budget-bar-fill.atlantico-over {
    background: linear-gradient(90deg, #c0392b, #e57368);
}

.atlantico-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.atlantico-sim-container .btn-primary {
    background: linear-gradient(135deg, #0f2740 0%, #27577f 100%);
    border: none;
    font-weight: 700;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 16px rgba(15,39,64,0.38);
    color: #f6f9fc;
}

.atlantico-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #163251 0%, #2f6492 100%);
    color: #ffffff;
}

.atlantico-sim-container .btn-outline-secondary {
    color: #44566c;
    border-color: rgba(27,60,94,0.35);
    border-radius: 10px;
}

.atlantico-sim-container .btn-outline-secondary:hover {
    background: rgba(27,60,94,0.08);
    color: #1b3c5e;
}

/* ---- Charts ---- */
.atlantico-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.atlantico-sim-chart-box {
    background: #ffffff;
    border: 1px solid rgba(27,60,94,0.12);
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 18px rgba(15,39,64,0.08);
    min-height: 320px;
}

/* ---- History ---- */
.atlantico-sim-history {
    background: #ffffff;
    border: 1px solid rgba(27,60,94,0.12);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 18px rgba(15,39,64,0.08);
}

.atlantico-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #1b3c5e;
    font-family: Georgia, 'Times New Roman', serif;
}

.atlantico-sim-history table {
    color: #2c3a4b;
    margin-bottom: 0;
}

.atlantico-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(27,60,94,0.04);
}

.atlantico-sim-history th {
    color: #647689;
    border-color: rgba(27,60,94,0.18);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.atlantico-sim-history td {
    border-color: rgba(27,60,94,0.1);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .atlantico-sim-container {
        padding: 12px;
    }
    .atlantico-sim-header h1 {
        font-size: 1.45rem;
    }
    .atlantico-sim-kpi-cards,
    .atlantico-sim-kpi-cards-secondary {
        grid-template-columns: 1fr 1fr;
    }
    .atlantico-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .atlantico-sim-charts {
        grid-template-columns: 1fr;
    }
    .atlantico-sim-kpi-value {
        font-size: 2.1rem;
    }
    .atlantico-sim-days-tag {
        margin-left: 0;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.dp-completion { padding: 8px 4px 4px; }
.dp-cm-head { text-align: center; margin-bottom: 16px; }
.dp-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #5b8def; }
.dp-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8aa0bf; }
.dp-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #eaf0f8; }
.dp-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.dp-cm-yes { background: rgba(74,200,140,0.16); color: #4ac88c; border: 1px solid rgba(74,200,140,0.45); }
.dp-cm-no { background: rgba(255,120,110,0.14); color: #ff8c82; border: 1px solid rgba(255,120,110,0.5); }
.dp-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.dp-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(91,141,239,0.08); border: 1px solid rgba(91,141,239,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.dp-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #5b8def; }
.dp-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #8aa0bf; text-transform: uppercase; letter-spacing: 0.03em; }
.dp-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #eaf0f8; }
.dp-cm-insights { margin: 0; padding-left: 20px; }
.dp-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #c6d2e4; }

