(function() {
    'use strict';

    class DesignProgramAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Design the Program';
            this.version = '1.1.0';

            // Hard constraints from the Banco Verde RFP.
            this.BUDGET_CAP = 1200;   // EUR thousands, Cohort 1, no co-funding
            this.DAYS_CAP = 4;        // in-person days off the branch floor, hard
            this.LEARNERS = 600;

            // In-person economics: EUR 1,900 / learner-day x 600 learners = EUR 1,140k / day.
            // Scaled to "intensive" budget: ~EUR 114k buys roughly one in-person day for 600
            // (regional waves, shared venues, blended faculty), so 4 days ~= EUR 456k.
            this.INPERSON_PER_DAY_K = 114;

            // Evidence strength per euro for behaviour change (70-20-10 weighted).
            // Sustainment and in-person practice carry transfer; digital barely moves behaviour.
            this.EVIDENCE = {
                inperson:    0.040,   // strong, but day-capped and dear
                virtual:     0.022,   // scales, mid evidence
                digital:     0.006,   // cheap, weak behaviour evidence
                sustainment: 0.052    // where transfer actually happens (months 4-9)
            };

            // Faculty multipliers on behaviour-change evidence.
            this.FACULTY = {
                senior:  { evidence: 1.15, costMult: 1.0,  label: 'senior' },
                blended: { evidence: 1.00, costMult: 1.0,  label: 'blended' },
                junior:  { evidence: 0.80, costMult: 1.0,  label: 'junior' }
            };

            // Diagnosis target: alignment with the three board metrics.
            // coaching = right; product = the failed-vendor trap; leadership = vague; mixed = diffuse.
            this.DIAGNOSIS = {
                coaching:   { alignGain: 30, behaviourMult: 1.00, ownable: true },
                product:    { alignGain: -22, behaviourMult: 0.55, ownable: false },
                leadership: { alignGain: 4,  behaviourMult: 0.78, ownable: false },
                mixed:      { alignGain: -6, behaviourMult: 0.80, ownable: false }
            };

            // Evaluation level: how far past Level 1 the measurement plan reaches.
            this.MEASUREMENT = {
                roi:       { credGain: 34, ceiling: 100 },
                behaviour: { credGain: 22, ceiling: 78 },
                learning:  { credGain: 10, ceiling: 55 },
                reaction:  { credGain: -14, ceiling: 32 }
            };

            this.ROUNDS = [
                {
                    nameEn: 'Diagnose the Capability Gap',
                    nameEs: 'Diagnostica la Brecha de Capacidad',
                    briefingEn: `<strong>14 September 2026 — the make-or-break brief lands.</strong> Banco Verde, a EUR 9-billion Iberian retail bank with 4,800 employees, has just merged two regional networks. Its closed-bid RFP asks for a <em>“Branch Leadership Transformation”</em>: <strong>600 branch and area managers</strong> must shift from transactional supervision to advisory, data-driven coaching of front-line teams. You have <strong>10 working days</strong> to submit a design, a measurement plan, and a fixed price.<br><br>You hold three conflicting voices. The <strong>CLO</strong> is explicit: the prior vendor was dismissed after a <strong>EUR 1.1M</strong> programme produced glowing <em>“smile sheets”</em> but <strong>zero movement</strong> on the only metrics the board tracks — <strong>+6 pp cross-sell, −15% attrition, manager NPS ≥ +30</strong>. The <strong>Head of Retail</strong> (loudest in the room) wants <em>product knowledge</em>. A branch-manager focus group just wants relief. Heilbrunn's discipline here is Pimentel's craft: <strong>a programme is a business intervention, judged by impact, not activity</strong>. Before you choose a single format, run a real <strong>learning-needs analysis</strong>: separate the stated request from the underlying capability gap and the business problem, and name the behaviour that actually moves the board metrics. Design backward from the outcome — not from the loudest sponsor.`,
                    briefingEs: `<strong>14 de septiembre de 2026 — llega el encargo decisivo.</strong> Banco Verde, un banco minorista ibérico de EUR 9.000 millones en activos y 4.800 empleados, acaba de fusionar dos redes regionales. Su RFP de puja cerrada pide una <em>“Transformación del Liderazgo en Oficina”</em>: <strong>600 directores de oficina y de zona</strong> deben pasar de la supervisión transaccional al <em>coaching</em> asesor basado en datos de sus equipos de primera línea. Tienes <strong>10 días hábiles</strong> para presentar diseño, plan de medición y precio fijo.<br><br>Tienes tres voces en conflicto. El <strong>CLO</strong> es tajante: al proveedor anterior lo despidieron tras un programa de <strong>EUR 1,1M</strong> que produjo <em>“encuestas de satisfacción”</em> brillantes pero <strong>cero movimiento</strong> en las únicas métricas que sigue el consejo — <strong>+6 pp de venta cruzada, −15% de rotación, NPS de directivos ≥ +30</strong>. El <strong>Director de Banca Minorista</strong> (el más ruidoso) quiere <em>conocimiento de producto</em>. Un grupo focal de directores de oficina solo busca alivio. La disciplina de Pimentel aquí: <strong>un programa es una intervención de negocio, juzgada por su impacto, no por la actividad</strong>. Antes de elegir un solo formato, haz un verdadero <strong>análisis de necesidades de aprendizaje</strong>: separa la petición declarada de la brecha real de capacidad y el problema de negocio, y nombra el comportamiento que de verdad mueve las métricas del consejo. Diseña desde el resultado — no desde el patrocinador más ruidoso.`,
                    eventEn: null,
                    eventEs: null
                },
                {
                    nameEn: 'Design the Format Mix Under the Caps',
                    nameEs: 'Diseña el Mix de Formatos Bajo los Topes',
                    briefingEn: `Your gap statement is on the wall. Now architect the programme under <strong>two hard caps</strong>: <strong>EUR 1,200,000</strong> all-in for 600 learners (EUR 2,000 each, no client co-funding) and a maximum of <strong>4 in-person days</strong> off the branch floor — peak Nov–Dec is fully blocked.<br><br>Allocate the budget across modalities, each with its own cost-per-learner and its own <em>behaviour-change evidence</em>. <strong>In-person intensives</strong> change behaviour best but are dear (~EUR 1,900/learner-day) and burn your 4-day cap fast. <strong>Virtual-live cohorts</strong> scale without floor time at mid evidence. <strong>Self-paced digital</strong> is the cheapest and most scalable but moves behaviour least — good for foundations, weak for coaching habits. And the <strong>sustainment tail</strong> — coaching circles, manager-led practice, reinforcement in months 4–9 — is where <strong>70-20-10</strong> says transfer actually happens. Cheap formats scale but rarely change behaviour; high-touch formats change behaviour but blow the budget and the time cap. Decide your <strong>faculty</strong> (practitioner-coaches transfer more than junior academics) and whether to <strong>segment</strong> the 600 — a senior area manager and a first-time branch lead do not share the same gap. You cannot fund everything.`,
                    briefingEs: `Tu enunciado de brecha está en la pizarra. Ahora diseña el programa bajo <strong>dos topes duros</strong>: <strong>EUR 1.200.000</strong> total para 600 alumnos (EUR 2.000 cada uno, sin cofinanciación del cliente) y un máximo de <strong>4 días presenciales</strong> fuera de la oficina — el pico de noviembre-diciembre está totalmente bloqueado.<br><br>Reparte el presupuesto entre modalidades, cada una con su coste por alumno y su <em>evidencia de cambio de comportamiento</em>. Las <strong>intensivas presenciales</strong> cambian mejor el comportamiento pero son caras (~EUR 1.900/alumno-día) y consumen rápido tu tope de 4 días. Las <strong>cohortes virtuales en directo</strong> escalan sin tiempo fuera de oficina con evidencia media. El <strong>digital autodirigido</strong> es lo más barato y escalable pero mueve menos el comportamiento — bueno para fundamentos, débil para hábitos de coaching. Y la <strong>fase de sostenimiento</strong> — círculos de coaching, práctica liderada por el jefe, refuerzo en los meses 4–9 — es donde el <strong>70-20-10</strong> dice que la transferencia de verdad ocurre. Los formatos baratos escalan pero rara vez cambian comportamiento; los de alto contacto lo cambian pero revientan presupuesto y tope de tiempo. Decide tu <strong>profesorado</strong> (los practitioner-coaches transfieren más que los académicos junior) y si <strong>segmentar</strong> a los 600 — un director de zona sénior y un jefe de oficina novel no comparten la misma brecha. No puedes financiarlo todo.`,
                    eventEn: `⚠️ <strong>Capacity reminder from the CLO:</strong> “The 600 managers cannot leave branches for more than 4 days, full stop. Peak season is blocked. Anything you build in-person beyond that is a non-starter — move it to virtual or manager-led practice.”`,
                    eventEs: `⚠️ <strong>Recordatorio de capacidad del CLO:</strong> «Los 600 directivos no pueden salir de las oficinas más de 4 días, punto. La temporada alta está bloqueada. Todo lo presencial por encima de eso es inviable — pásalo a virtual o a práctica liderada por el jefe.»`
                },
                {
                    nameEn: 'Build the Measurement Plan & Impact Case',
                    nameEs: 'Construye el Plan de Medición y el Caso de Impacto',
                    briefingEn: `Now design the evaluation that satisfies a <strong>sceptical board</strong>. Map each board metric to a measurement method along the <strong>Kirkpatrick / Phillips hierarchy</strong> — reaction (L1), learning (L2), behaviour (L3), business result (L4), and ROI (L5) — and set the <strong>baseline-and-control</strong> approach. Choose <strong>leading indicators</strong> that surface early, at the <strong>90-day checkpoint</strong>, so a lagging metric can be corrected mid-flight rather than discovered at month nine.<br><br>The CLO has <em>already seen</em> a 4.6/5 satisfaction score and 94% completion — right before cross-sell stayed flat. Reaction and completion are not the levels the board rewards. Push your plan into behaviour and business result: where does a branch manager visibly change what they do on Monday, and how do you see it move? Then build the projected-impact case — cross-sell lift, attrition savings in euros, and the resulting ROI on EUR 1.2M — and decide how aggressively to commit. <em>Promise a clean ROI you cannot defend and you walk straight into the clawback.</em>`,
                    briefingEs: `Ahora diseña la evaluación que convence a un <strong>consejo escéptico</strong>. Conecta cada métrica del consejo con un método de medición a lo largo de la <strong>jerarquía de Kirkpatrick / Phillips</strong> — reacción (N1), aprendizaje (N2), comportamiento (N3), resultado de negocio (N4) y ROI (N5) — y fija el enfoque de <strong>línea base y grupo de control</strong>. Elige <strong>indicadores adelantados</strong> que afloren pronto, en el <strong>punto de control de los 90 días</strong>, para corregir sobre la marcha una métrica rezagada en vez de descubrirla en el mes nueve.<br><br>El CLO <em>ya ha visto</em> un 4,6/5 de satisfacción y un 94% de finalización — justo antes de que la venta cruzada se quedara plana. Reacción y finalización no son los niveles que premia el consejo. Lleva tu plan hasta comportamiento y resultado de negocio: ¿dónde cambia visiblemente un director de oficina lo que hace el lunes, y cómo lo ves moverse? Después construye el caso de impacto proyectado — incremento de venta cruzada, ahorro de rotación en euros y el ROI resultante sobre los EUR 1,2M — y decide con qué agresividad comprometerte. <em>Prometer un ROI limpio que no puedes defender es entrar directo en el clawback.</em>`,
                    eventEn: `📊 <strong>Attribution warning:</strong> A new advisory product range launches the same quarter the programme closes. Any cross-sell lift you claim will be challenged — “how much is your programme versus the new range?” Without a baseline and control, you cannot isolate the effect.`,
                    eventEs: `📊 <strong>Aviso de atribución:</strong> Una nueva gama de productos de asesoría se lanza el mismo trimestre en que cierra el programa. Cualquier incremento de venta cruzada que reclames será cuestionado — «¿cuánto es tu programa frente a la nueva gama?». Sin línea base ni control, no puedes aislar el efecto.`
                },
                {
                    nameEn: 'Pitch, Price & Defend',
                    nameEs: 'Presenta, Pon Precio y Defiende',
                    briefingEn: `🏛️ <strong>THE PITCH.</strong> You present a 4-minute proposal to the facilitator playing the Banco Verde <strong>CLO and CFO</strong>. Finalise the fixed price within the EUR 1.2M ceiling and set the <strong>impact-guarantee terms</strong> you will stand behind. The <strong>CFO</strong> presses on the guarantee: <em>“What's your baseline, your control group, and how much of the lift is you versus the new product range?”</em> The <strong>CLO</strong> presses on learner time away from branches.<br><br>Set your <strong>guarantee stance</strong>. A <em>defensible</em> claim commits only to what your baseline and control can prove. An <em>aggressive</em> headline ROI may win the room — but if a metric misses at nine months, the impact clause triggers a <strong>30% (EUR 360,000) clawback</strong> and you lose the flagship reference. A <em>conditional</em> guarantee ties payment to a 90-day recover plan. <em>Dropping</em> the guarantee prices low but forfeits Atlântico's distinguishing promise. Two rivals are also bidding: lose, and a <strong>EUR 3.4M three-cohort pipeline</strong> walks. Win on a design that moves the metrics the last vendor could not — and only commit to what you can defend.`,
                    briefingEs: `🏛️ <strong>EL PITCH.</strong> Presentas una propuesta de 4 minutos al facilitador en el papel de <strong>CLO y CFO</strong> de Banco Verde. Cierra el precio fijo dentro del techo de EUR 1,2M y fija los <strong>términos de la garantía de impacto</strong> que vas a sostener. El <strong>CFO</strong> aprieta sobre la garantía: <em>«¿Cuál es tu línea base, tu grupo de control y cuánto del incremento eres tú frente a la nueva gama de productos?»</em>. El <strong>CLO</strong> aprieta sobre el tiempo de los alumnos fuera de las oficinas.<br><br>Fija tu <strong>postura de garantía</strong>. Una propuesta <em>defendible</em> compromete solo lo que tu línea base y control pueden probar. Un ROI titular <em>agresivo</em> puede ganar la sala — pero si una métrica falla a los nueve meses, la cláusula de impacto activa un <strong>clawback del 30% (EUR 360.000)</strong> y pierdes el cliente de referencia. Una garantía <em>condicional</em> liga el pago a un plan de recuperación a 90 días. <em>Retirar</em> la garantía abarata el precio pero renuncia a la promesa distintiva de Atlântico. Dos rivales también pujan: si pierdes, se va una <strong>cartera de EUR 3,4M a tres cohortes</strong>. Gana con un diseño que mueva las métricas que el último proveedor no pudo — y comprométete solo a lo que puedas defender.`,
                    eventEn: `🎙️ <strong>Two challenges at the table:</strong> The CFO asks “why should we believe this ROI when the last vendor's numbers looked great too?” while the CLO asks “how is this only 4 days off the floor?” Only a design with defensible measurement and a fit-within-caps mix answers both.`,
                    eventEs: `🎙️ <strong>Dos retos en la mesa:</strong> El CFO pregunta «¿por qué creer este ROI si los números del último proveedor también pintaban bien?» mientras el CLO pregunta «¿cómo es esto solo 4 días fuera de la oficina?». Solo un diseño con medición defendible y un mix dentro de los topes responde a ambos.`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    behaviour: 28,        // behaviour-change evidence (hero, 0-100)
                    alignment: 40,        // alignment with the three board metrics (0-100)
                    measurement: 22,      // measurement credibility past Level 1 (0-100)
                    fit: 50,              // budget & time fit (0-100)
                    budgetSpent: 0,       // cumulative EUR thousands committed this round
                    inpersonDays: 0,      // in-person days implied by the in-person budget
                    projectedRoi: 0,      // x multiple, resolved from the case
                    bidStatus: 'design',  // 'design' | 'won' | 'lost'
                    clawback: 0,          // EUR thousands clawed back if targets miss
                    targetsHit: 0,        // 0..3 board metrics projected to move
                    pipeline: 0,          // EUR M pipeline secured (3.4) or forfeited
                    outcome: 'inprogress',// 'inprogress' | 'won' | 'lost'
                    behaviourHistory: [],
                    alignmentHistory: [],
                    measurementHistory: [],
                    fitHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diagnosis: 'coaching',
                    lnaDepth: 40,
                    inperson: 380,
                    virtual: 270,
                    digital: 72,
                    sustainment: 200,
                    faculty: 'blended',
                    segment: 'segmented',
                    measurement: 'roi',
                    guarantee: 'defensible'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var diagEl = document.getElementById('diagnosisInput');
            var lnaEl = document.getElementById('lnaDepthInput');
            var inpersonEl = document.getElementById('inpersonInput');
            var virtualEl = document.getElementById('virtualInput');
            var digitalEl = document.getElementById('digitalInput');
            var sustainmentEl = document.getElementById('sustainmentInput');
            var facultyEl = document.getElementById('facultyInput');
            var segmentEl = document.getElementById('segmentInput');
            var measEl = document.getElementById('measurementInput');
            var guarEl = document.getElementById('guaranteeInput');

            if (diagEl) decisions.diagnosis = diagEl.value;
            if (lnaEl) decisions.lnaDepth = parseInt(lnaEl.value, 10);
            if (inpersonEl) decisions.inperson = parseInt(inpersonEl.value, 10);
            if (virtualEl) decisions.virtual = parseInt(virtualEl.value, 10);
            if (digitalEl) decisions.digital = parseInt(digitalEl.value, 10);
            if (sustainmentEl) decisions.sustainment = parseInt(sustainmentEl.value, 10);
            if (facultyEl) decisions.faculty = facultyEl.value;
            if (segmentEl) decisions.segment = segmentEl.value;
            if (measEl) decisions.measurement = measEl.value;
            if (guarEl) decisions.guarantee = guarEl.value;

            if (!this.DIAGNOSIS[decisions.diagnosis]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('diagnosis_warning'), 'warning');
                return false;
            }
            if (!Number.isFinite(decisions.lnaDepth) || decisions.lnaDepth < 0 || decisions.lnaDepth > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('lna_warning'), 'warning');
                return false;
            }
            var lines = [decisions.inperson, decisions.virtual, decisions.digital, decisions.sustainment];
            for (var i = 0; i < lines.length; i++) {
                if (!Number.isFinite(lines[i]) || lines[i] < 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                    return false;
                }
            }
            var total = decisions.inperson + decisions.virtual + decisions.digital + decisions.sustainment;
            if (total > this.BUDGET_CAP) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_over_warning'), 'warning');
                return false;
            }
            if (!this.FACULTY[decisions.faculty]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('faculty_warning'), 'warning');
                return false;
            }
            if (['segmented', 'uniform'].indexOf(decisions.segment) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('segment_warning'), 'warning');
                return false;
            }
            if (!this.MEASUREMENT[decisions.measurement]) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('measurement_warning'), 'warning');
                return false;
            }
            if (['defensible', 'aggressive', 'conditional', 'none'].indexOf(decisions.guarantee) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('guarantee_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var diag = this.DIAGNOSIS[d.diagnosis];
            var fac = this.FACULTY[d.faculty];
            var meas = this.MEASUREMENT[d.measurement];

            // ---- LNA depth: trustworthiness of the whole design. Building before diagnosing caps gains. ----
            var depthFactor = 0.45 + (d.lnaDepth / 100) * 0.55; // 0.45 .. 1.0

            // ---- Budget mechanics (EUR thousands) ----
            var total = d.inperson + d.virtual + d.digital + d.sustainment;
            ds.budgetSpent = total;
            // In-person days implied by the in-person spend.
            ds.inpersonDays = Math.round((d.inperson / this.INPERSON_PER_DAY_K) * 10) / 10;
            var daysOver = ds.inpersonDays > this.DAYS_CAP;
            var overBudget = total > this.BUDGET_CAP;

            // ---- Behaviour-Change Evidence (hero KPI) ----
            // Each modality contributes evidence per euro, faculty-weighted, gated by diagnosis & depth.
            var rawEvidence =
                d.inperson * this.EVIDENCE.inperson +
                d.virtual * this.EVIDENCE.virtual +
                d.digital * this.EVIDENCE.digital +
                d.sustainment * this.EVIDENCE.sustainment;
            rawEvidence = rawEvidence * fac.evidence * diag.behaviourMult * depthFactor;
            // Segmentation makes the same euro land better (right depth for the right learner).
            if (d.segment === 'segmented') rawEvidence *= 1.08; else rawEvidence *= 0.92;
            // In-person beyond the 4-day cap delivers nothing usable (managers can't attend).
            if (daysOver) {
                var wastedDays = ds.inpersonDays - this.DAYS_CAP;
                rawEvidence -= wastedDays * 2.4;
            }
            var behaviourGain = rawEvidence * 0.5;
            ds.behaviour = Math.max(0, Math.min(100, Math.round(ds.behaviour + behaviourGain)));

            // ---- Stakeholder Alignment (board metrics vs loudest sponsor) ----
            var alignDelta = diag.alignGain * (0.55 + depthFactor * 0.45);
            // Pleasing the loudest sponsor with product knowledge erodes board alignment further over time.
            if (d.diagnosis === 'product') alignDelta -= 4;
            ds.alignment = Math.max(0, Math.min(100, Math.round(ds.alignment + alignDelta)));

            // ---- Measurement Credibility (Kirkpatrick / Phillips) ----
            var credDelta = meas.credGain * (0.6 + depthFactor * 0.4);
            // Credibility cannot exceed the ceiling of the chosen evaluation level.
            var credTarget = Math.min(meas.ceiling, ds.measurement + credDelta);
            // Round 3 is the dedicated measurement round: the choice carries extra weight here.
            if (period === 3) credTarget = Math.min(meas.ceiling, ds.measurement + credDelta * 1.25);
            ds.measurement = Math.max(0, Math.min(meas.ceiling, Math.round(credTarget)));

            // ---- Budget & Time Fit ----
            var fitScore = 78; // start from "comfortably within both caps"
            if (overBudget) fitScore -= Math.min(50, (total - this.BUDGET_CAP) / 12);
            // Spending too close to nothing on sustainment is a fit/quality problem (front-loaded launch).
            var sustainShare = total > 0 ? d.sustainment / total : 0;
            if (sustainShare < 0.12) fitScore -= 20;       // starved the tail
            else if (sustainShare >= 0.18) fitScore += 8;  // funded transfer
            if (daysOver) fitScore -= Math.min(40, (ds.inpersonDays - this.DAYS_CAP) * 12);
            if (d.segment === 'segmented') fitScore += 6;   // less wasted budget
            // Leaving headroom unused is fine; spending the full ceiling efficiently is the target.
            ds.fit = Math.max(0, Math.min(100, Math.round(fitScore)));

            // ---- Projected ROI / impact case (visible from round 3) ----
            if (period >= 3) {
                // Defensible ROI scales with behaviour evidence and measurement credibility.
                var baseRoi = (ds.behaviour / 100) * 3.4 + (ds.measurement / 100) * 1.2;
                if (d.guarantee === 'aggressive') {
                    // Headline number ignores attribution -> not defensible, credibility suffers.
                    ds.projectedRoi = 4.2;
                    ds.measurement = Math.max(0, ds.measurement - 6);
                } else if (d.guarantee === 'none') {
                    ds.projectedRoi = Math.round(baseRoi * 0.8 * 10) / 10;
                } else if (d.guarantee === 'conditional') {
                    ds.projectedRoi = Math.round((baseRoi + 0.2) * 10) / 10;
                } else {
                    ds.projectedRoi = Math.round(baseRoi * 10) / 10;
                }
            }

            // ---- Round 4: bid resolution, targets, clawback, pipeline ----
            if (period === 4) {
                // Guarantee stance arbitration at the table.
                if (d.guarantee === 'aggressive') {
                    ds.alignment = Math.min(100, ds.alignment + 3); // dazzles in the room
                } else if (d.guarantee === 'defensible' || d.guarantee === 'conditional') {
                    ds.measurement = Math.min(100, ds.measurement + 4); // CFO trusts the numbers
                } else if (d.guarantee === 'none') {
                    ds.alignment = Math.max(0, ds.alignment - 4); // forfeits the distinguishing promise
                }

                // How many of the three board metrics are projected to move at 9 months.
                // Requires behaviour change, board alignment, within-cap delivery, and —
                // for the attrition target — a funded sustainment tail (70-20-10 transfer).
                var finalSustainShare = total > 0 ? d.sustainment / total : 0;
                var sustainmentFunded = finalSustainShare >= 0.18 && !daysOver && !overBudget;
                var hits = 0;
                if (ds.behaviour >= 58 && ds.alignment >= 62) hits++;            // +6 pp cross-sell
                if (ds.behaviour >= 50 && sustainmentFunded) hits++;             // -15% attrition (transfer tail)
                if (ds.alignment >= 58 && ds.measurement >= 48) hits++;          // manager NPS >= +30
                ds.targetsHit = hits;

                // Bid win: a credible, fit-within-caps design that beats two rivals and
                // projects to move at least two of the three board metrics (the last vendor
                // was fired for moving none). Starving the sustainment tail caps this at one.
                var bidWon = ds.behaviour >= 52 && ds.alignment >= 58 &&
                             ds.measurement >= 50 && ds.fit >= 55 &&
                             !daysOver && !overBudget && hits >= 2;
                ds.bidStatus = bidWon ? 'won' : 'lost';

                if (bidWon) {
                    // The impact guarantee covers ALL THREE board metrics. The clawback fires
                    // whenever a metric the firm contractually committed to misses at 9 months.
                    // Only 'none' carries no fee exposure (but it forfeits the flagship promise).
                    var guaranteeExposed = (d.guarantee === 'aggressive' || d.guarantee === 'defensible' || d.guarantee === 'conditional');
                    if (!guaranteeExposed) {
                        ds.clawback = 0;
                    } else if (hits >= 3) {
                        ds.clawback = 0;            // all three move -> guarantee held
                    } else if (d.guarantee === 'conditional') {
                        ds.clawback = 120;          // partial; the 90-day recover plan softens it
                    } else {
                        ds.clawback = 360;          // 30% of EUR 1.2M, full clawback
                    }
                    // A clean win = guarantee held AND all three board metrics projected to move.
                    var guaranteeHeld = ds.clawback === 0 && hits >= 3;
                    ds.pipeline = guaranteeHeld ? 3.4 : 0;
                    ds.outcome = guaranteeHeld ? 'won' : 'lost';
                } else {
                    ds.clawback = 0;
                    ds.pipeline = 0; // lost bid forfeits the three-cohort pipeline
                    ds.outcome = 'lost';
                }
            } else {
                ds.outcome = 'inprogress';
            }

            // ---- History ----
            ds.behaviourHistory.push(ds.behaviour);
            ds.alignmentHistory.push(ds.alignment);
            ds.measurementHistory.push(ds.measurement);
            ds.fitHistory.push(ds.fit);

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: period,
                diagnosis: d.diagnosis,
                lnaDepth: d.lnaDepth,
                inperson: d.inperson,
                virtual: d.virtual,
                digital: d.digital,
                sustainment: d.sustainment,
                faculty: d.faculty,
                segment: d.segment,
                measurementLevel: d.measurement,
                guarantee: d.guarantee,
                behaviour: ds.behaviour,
                alignment: ds.alignment,
                measurement: ds.measurement,
                fit: ds.fit,
                budgetSpent: ds.budgetSpent,
                inpersonDays: ds.inpersonDays,
                projectedRoi: ds.projectedRoi,
                bidStatus: ds.bidStatus,
                clawback: ds.clawback,
                targetsHit: ds.targetsHit,
                pipeline: ds.pipeline,
                outcome: ds.outcome
            };
        }

        _updateBars(ds) {
            var b = document.getElementById('behaviourBar');
            var a = document.getElementById('alignmentBar');
            var m = document.getElementById('measurementBar');
            var f = document.getElementById('fitBar');
            if (b) b.style.width = ds.behaviour + '%';
            if (a) a.style.width = ds.alignment + '%';
            if (m) m.style.width = ds.measurement + '%';
            if (f) f.style.width = ds.fit + '%';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : 'en';
            } catch (e) { lang = 'en'; }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }

            this._updateBudgetMeter();
        }

        _updateBudgetMeter() {
            var iEl = document.getElementById('inpersonInput');
            var vEl = document.getElementById('virtualInput');
            var dEl = document.getElementById('digitalInput');
            var sEl = document.getElementById('sustainmentInput');
            if (!iEl || !vEl || !dEl || !sEl) return;
            var inp = parseInt(iEl.value, 10) || 0;
            var vir = parseInt(vEl.value, 10) || 0;
            var dig = parseInt(dEl.value, 10) || 0;
            var sus = parseInt(sEl.value, 10) || 0;
            var total = inp + vir + dig + sus;

            var allocEl = document.getElementById('allocatedDisplay');
            if (allocEl) allocEl.textContent = '€' + total.toLocaleString() + 'k';

            var bar = document.getElementById('budgetMeterBar');
            if (bar) {
                var pct = Math.min(100, Math.round((total / this.BUDGET_CAP) * 100));
                bar.style.width = pct + '%';
                if (total > this.BUDGET_CAP) {
                    bar.classList.add('atlantico-over');
                    bar.style.width = '100%';
                } else {
                    bar.classList.remove('atlantico-over');
                }
            }

            var days = Math.round((inp / this.INPERSON_PER_DAY_K) * 10) / 10;
            var tag = document.getElementById('daysTag');
            if (tag) {
                var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t : function(k) { return k; };
                tag.textContent = days + ' / ' + this.DAYS_CAP + ' ' + t('days_unit');
                if (days > this.DAYS_CAP) tag.classList.add('atlantico-days-over');
                else tag.classList.remove('atlantico-days-over');
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('behaviourDisplay', 'domainState.behaviour');
            uiManager.bind('alignmentDisplay', 'domainState.alignment');
            uiManager.bind('measurementDisplay', 'domainState.measurement');
            uiManager.bind('fitDisplay', 'domainState.fit');
            uiManager.bind('budgetDisplay', 'domainState.budgetSpent', function(v) {
                var remaining = (1200 - (v || 0)) / 1000;
                return '€' + remaining.toFixed(2) + 'M';
            });
            uiManager.bind('daysDisplay', 'domainState.inpersonDays', function(v) {
                return (v || 0) + ' / 4';
            });
            uiManager.bind('roiDisplay', 'domainState.projectedRoi', function(v) {
                if (!v) return '—';
                return v.toFixed(1) + 'x';
            });
            uiManager.bind('deadlineDisplay', 'currentPeriod', function(v) {
                var days = [10, 7, 4, 1];
                return days[Math.min(v - 1, 3)];
            });
            uiManager.bind('bidDisplay', 'domainState.bidStatus', function(v) {
                var t = window.mySimulation.t;
                if (v === 'won') return t('bid_won');
                if (v === 'lost') return t('bid_lost');
                return t('bid_pending');
            });

            var self = this;
            ['inpersonInput', 'virtualInput', 'digitalInput', 'sustainmentInput'].forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() { self._updateBudgetMeter(); });
                }
            });
            this._updateBudgetMeter();
        }

        getChartConfig() {
            return {
                indexChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Behaviour-Change Evidence', data: [], borderColor: '#b9821f', backgroundColor: 'rgba(185,130,31,0.12)', borderWidth: 3, fill: false, tension: 0.3 },
                            { label: 'Stakeholder Alignment', data: [], borderColor: '#1b3c5e', backgroundColor: 'rgba(27,60,94,0.12)', borderWidth: 3, fill: false, tension: 0.3 },
                            { label: 'Measurement Credibility', data: [], borderColor: '#2f7d6a', backgroundColor: 'rgba(47,125,106,0.12)', borderWidth: 3, fill: false, tension: 0.3 },
                            { label: 'Budget & Time Fit', data: [], borderColor: '#6a4a8c', backgroundColor: 'rgba(106,74,140,0.12)', borderWidth: 3, fill: false, tension: 0.3 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Design Indices by Round' },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Index (0-100)' } }
                        }
