                    ]
                }
            };
        }

        // Composite 0-100 for the reporting/grading layer (results_utils.php reads
        // domainState.performance.overallScore). Same math as getPerformanceSummary's totalScore.
        _composite(x) {
            var beh = x.behaviour || 0, ali = x.alignment || 0, mea = x.measurement || 0, fit = x.fit || 0;
            var s = Math.round(beh * 0.35 + ali * 0.25 + mea * 0.22 + fit * 0.18);
            if (x.bidStatus === 'won') s = Math.min(100, s + 6);
            if (x.bidStatus === 'lost') s = Math.max(0, s - 8);
            if ((x.clawback || 0) > 0) s = Math.max(0, s - 10);
            return Math.max(0, Math.min(100, s));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var beh = r.behaviour || 0;
            var ali = r.alignment || 0;
            var mea = r.measurement || 0;
            var fit = r.fit || 0;
            var roi = r.projectedRoi || 0;
            var claw = r.clawback || 0;
            var hits = r.targetsHit || 0;

            // Composite: behaviour evidence (35%), alignment (25%), measurement (22%), fit (18%).
            var totalScore = Math.round(beh * 0.35 + ali * 0.25 + mea * 0.22 + fit * 0.18);
            if (r.bidStatus === 'won') totalScore = Math.min(100, totalScore + 6);
            if (r.bidStatus === 'lost') totalScore = Math.max(0, totalScore - 8);
            if (claw > 0) totalScore = Math.max(0, totalScore - 10);
            totalScore = Math.max(0, Math.min(100, totalScore));

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){return window.mySimulation.t(k);} : function(k){return k;};
            var performanceKey = 'grade_activity';
            if (totalScore >= 78 && r.outcome === 'won') performanceKey = 'grade_architect';
            else if (totalScore >= 62) performanceKey = 'grade_director';
            else if (totalScore >= 45) performanceKey = 'grade_developing';

            var performance = T(performanceKey);
            var insights = [];

            // Diagnosis read-back
            var designedToBoard = history.some(function(h) { return h.results && h.results.diagnosis === 'coaching'; });
            if (designedToBoard) insights.push(T('ins_diag_yes'));
            else insights.push(T('ins_diag_no'));

            // Sustainment / 70-20-10
            var lastBudget = r.budgetSpent || 0;
            var lastSustain = r.sustainment || 0;
            var sustainShare = lastBudget > 0 ? lastSustain / lastBudget : 0;
            if (sustainShare >= 0.18) insights.push(T('ins_sustain_yes'));
            else insights.push(T('ins_sustain_no'));

            // Caps
            if (r.inpersonDays > 4) insights.push(T('ins_cap_inperson').replace('{n}', r.inpersonDays));
            if (r.budgetSpent > 1200) insights.push(T('ins_cap_budget'));

            // Measurement
            if (mea >= 50) insights.push(T('ins_meas_yes'));
            else insights.push(T('ins_meas_no'));

            // Guarantee / clawback
            if (claw > 0) insights.push(T('ins_clawback').replace('{n}', claw));
            else if (r.bidStatus === 'won') insights.push(T('ins_bid_won'));
            else insights.push(T('ins_bid_lost'));

            return {
                totalScore: totalScore,
                behaviour: beh,
                alignment: ali,
                measurement: mea,
                fit: fit,
                projectedRoi: roi,
                targetsHit: hits,
                clawback: claw,
                pipeline: r.pipeline || 0,
                bidStatus: r.bidStatus,
                outcome: r.outcome,
                overallScore: totalScore,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.overallScore === 'number' ? s.overallScore : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var won = s.bidStatus === 'won';
            var badge = won
                ? '<span class="dp-cm-badge dp-cm-yes">' + T('cm_won') + '</span>'
                : '<span class="dp-cm-badge dp-cm-no">' + T('cm_lost') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="dp-cm-metric"><span class="dp-cm-mv">' + Math.round(s.behaviour||0) + '</span><span class="dp-cm-ml">' + T('cm_m_behaviour') + '</span></div>'
                + '<div class="dp-cm-metric"><span class="dp-cm-mv">' + Math.round(s.alignment||0) + '</span><span class="dp-cm-ml">' + T('cm_m_alignment') + '</span></div>'
                + '<div class="dp-cm-metric"><span class="dp-cm-mv">' + Math.round(s.measurement||0) + '</span><span class="dp-cm-ml">' + T('cm_m_measurement') + '</span></div>'
                + '<div class="dp-cm-metric"><span class="dp-cm-mv">' + Math.round(s.fit||0) + '</span><span class="dp-cm-ml">' + T('cm_m_fit') + '</span></div>';
            return ''
                + '<div class="dp-completion">'
                +   '<div class="dp-cm-head">'
                +     '<div class="dp-cm-score">' + score + '<span class="dp-cm-score-max">/100</span></div>'
                +     '<div class="dp-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="dp-cm-metrics">' + metrics + '</div>'
                +   '<div class="dp-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="dp-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.outcome === 'won') return window.mySimulation.t('hint_won');
            if (results.outcome === 'lost' && state.currentPeriod >= 4) return window.mySimulation.t('hint_lost');
            if (results.diagnosis === 'product') return window.mySimulation.t('hint_product');
            if (results.diagnosis === 'leadership' || results.diagnosis === 'mixed') return window.mySimulation.t('hint_vague');
            if (results.inpersonDays > 4) return window.mySimulation.t('hint_days');
            if (results.budgetSpent > 1200) return window.mySimulation.t('hint_budget');
            if (results.measurement < 45) return window.mySimulation.t('hint_measurement');
            if (results.guarantee === 'aggressive') return window.mySimulation.t('hint_aggressive');
            var lastSustainShare = results.budgetSpent > 0 ? results.sustainment / results.budgetSpent : 0;
            if (lastSustainShare < 0.12) return window.mySimulation.t('hint_sustainment');
            return window.mySimulation.t('hint_good_progress');
        }

